#!/usr/bin/env python3
"""Canonical Git divergence/writer guard for EDARSAHUB Development.

Fail-closed. No pull, merge, rebase, reset --hard, clean or force-push.
"""
from __future__ import annotations

import argparse
import json
import os
import shutil
import subprocess
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

DEV_BRANCH = "Edarsahub_Desarrollo"
REMOTE = "origin"
LOCK_NAME = "git-writer.lock.d"
DEFAULT_LOCK_TTL_SECONDS = 7200


class GitGuardError(RuntimeError):
    def __init__(self, code: str, evidence: dict[str, Any] | None = None):
        super().__init__(code)
        self.code = code
        self.evidence = evidence or {}


def utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _run(repo: Path, *args: str, check: bool = True, env: dict[str, str] | None = None):
    result = subprocess.run(["git", *args], cwd=str(repo), text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env=env, check=False)
    if check and result.returncode != 0:
        raise GitGuardError("GIT_COMMAND_FAILED", {"args": list(args), "returncode": result.returncode, "output": (result.stdout or "")[-2000:]})
    return result


def _git_dir(repo: Path) -> Path:
    raw = _run(repo, "rev-parse", "--git-dir").stdout.strip()
    path = Path(raw)
    return (repo / path).resolve() if not path.is_absolute() else path.resolve()


def _status_counts(repo: Path) -> dict[str, int | bool]:
    lines = _run(repo, "status", "--porcelain=v1", "--untracked-files=all").stdout.splitlines()
    staged = unstaged = untracked = 0
    for line in lines:
        if line.startswith("??"):
            untracked += 1
            continue
        if len(line) >= 2:
            if line[0] != " ": staged += 1
            if line[1] != " ": unstaged += 1
    return {"worktree_dirty": bool(staged or unstaged or untracked), "staged_count": staged, "unstaged_count": unstaged, "untracked_count": untracked}


def inspect_repository(repo: Path, *, fetch: bool = True) -> dict[str, Any]:
    repo = repo.resolve()
    if fetch: _run(repo, "fetch", REMOTE, DEV_BRANCH)
    branch = _run(repo, "branch", "--show-current").stdout.strip()
    local = _run(repo, "rev-parse", "HEAD").stdout.strip()
    remote = _run(repo, "rev-parse", f"{REMOTE}/{DEV_BRANCH}").stdout.strip()
    merge = _run(repo, "merge-base", local, remote, check=False)
    merge_base = merge.stdout.strip() if merge.returncode == 0 else ""
    counts = _run(repo, "rev-list", "--left-right", "--count", f"{local}...{remote}").stdout.split()
    ahead, behind = (int(counts[0]), int(counts[1])) if len(counts) == 2 else (0, 0)
    dirty = _status_counts(repo)
    if dirty["worktree_dirty"]: classification = "DIRTY_WORKTREE"
    elif ahead == 0 and behind == 0: classification = "SYNC"
    elif ahead > 0 and behind == 0: classification = "LOCAL_AHEAD_ONLY"
    elif ahead == 0 and behind > 0: classification = "REMOTE_AHEAD_ONLY"
    else: classification = "DIVERGED"
    local_only = _run(repo, "log", "--format=%H", "--max-count=20", local, "--not", remote, check=False).stdout.splitlines()
    remote_only = _run(repo, "log", "--format=%H", "--max-count=20", remote, "--not", local, check=False).stdout.splitlines()
    return {"current_branch": branch, "local_head": local, "remote_head": remote, "merge_base": merge_base, "ahead_count": ahead, "behind_count": behind, **dirty, "classification": classification, "local_only_commits": local_only, "remote_only_commits": remote_only}


def mutation_policy(state: dict[str, Any], *, allow_local_ahead: bool = False) -> dict[str, Any]:
    if state.get("current_branch") != DEV_BRANCH: return {"allowed": False, "terminal_status": "GIT_DIVERGENCE_BLOCKED", "reason": "WRONG_CANONICAL_BRANCH"}
    if state.get("worktree_dirty"): return {"allowed": False, "terminal_status": "GIT_WORKTREE_NOT_CLEAN", "reason": "GIT_WORKTREE_NOT_CLEAN"}
    classification = state.get("classification")
    if classification == "SYNC": return {"allowed": True, "terminal_status": "CERTIFIED_GIT_SYNC", "reason": "SYNC"}
    if classification == "LOCAL_AHEAD_ONLY":
        if allow_local_ahead: return {"allowed": True, "terminal_status": "LOCAL_AHEAD_ONLY", "reason": "EXPLICIT_LOCAL_OWNER_POLICY"}
        return {"allowed": False, "terminal_status": "GIT_DIVERGENCE_BLOCKED", "reason": "LOCAL_AHEAD_OWNERSHIP_UNPROVEN"}
    if classification == "REMOTE_AHEAD_ONLY": return {"allowed": False, "terminal_status": "GIT_DIVERGENCE_BLOCKED", "reason": "NEEDS_FAST_FORWARD_REFRESH"}
    if classification == "DIVERGED": return {"allowed": False, "terminal_status": "GIT_DIVERGENCE_BLOCKED", "reason": "GIT_DIVERGENCE_BLOCKED"}
    return {"allowed": False, "terminal_status": "GIT_DIVERGENCE_BLOCKED", "reason": "UNKNOWN_GIT_STATE"}


def requires_writer_lock(mode: str) -> bool:
    return str(mode or "MUTATION") not in {"READ_ONLY", "READ_ONLY_SQL", "SOFTRESTAURANT_FULL_HISTORY_RESYNC", "MPRO_FULL_HISTORY_RESYNC", "ISCAM_DETAIL_BACKFILL", "ISCAM_PAYMENTS_ONLY_RESYNC", "SQL_MIGRATION_DEVELOPMENT"}


def _pid_alive(pid: int) -> bool:
    if pid <= 0: return False
    try:
        os.kill(pid, 0); return True
    except OSError:
        return False


def _read_json(path: Path) -> dict[str, Any]:
    try:
        data = json.loads(path.read_text(encoding="utf-8")); return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def acquire_writer_lock(repo: Path, *, job_id: str, owner: str, owner_pid: int | None = None, stale_after_seconds: int = DEFAULT_LOCK_TTL_SECONDS) -> dict[str, Any]:
    git_dir = _git_dir(repo.resolve())
    lock_dir = git_dir / "universal-worker-queue" / LOCK_NAME
    lock_dir.parent.mkdir(parents=True, exist_ok=True)
    pid = int(owner_pid or os.getpid())
    stale_evidence: dict[str, Any] | None = None
    if lock_dir.exists():
        previous = _read_json(lock_dir / "owner.json")
        created_epoch = float(previous.get("created_epoch") or 0)
        previous_pid = int(previous.get("owner_pid") or 0)
        age = max(0.0, time.time() - created_epoch) if created_epoch else float("inf")
        stale = age >= stale_after_seconds and not _pid_alive(previous_pid)
        if not stale: raise GitGuardError("GIT_LOCK_BUSY", {"lock_owner": previous, "lock_dir": str(lock_dir), "age_seconds": age})
        stale_name = lock_dir.with_name(f"git-writer.lock.stale.{int(time.time())}.{previous.get('job_id','unknown')}")
        os.replace(lock_dir, stale_name)
        stale_evidence = {"previous": previous, "preserved_at": str(stale_name), "age_seconds": age}
    try:
        lock_dir.mkdir()
    except FileExistsError as exc:
        raise GitGuardError("GIT_LOCK_BUSY", {"lock_dir": str(lock_dir)}) from exc
    token = {"job_id": job_id, "owner": owner, "owner_pid": pid, "created_at_utc": utc_now(), "created_epoch": time.time(), "lock_dir": str(lock_dir), "stale_lock_recovered": stale_evidence}
    (lock_dir / "owner.json").write_text(json.dumps(token, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return token


def release_writer_lock(repo: Path, token: dict[str, Any]) -> None:
    lock_dir = Path(str(token.get("lock_dir") or ""))
    if not lock_dir.is_dir(): raise GitGuardError("GIT_LOCK_BUSY", {"reason": "LOCK_DIRECTORY_MISSING"})
    current = _read_json(lock_dir / "owner.json")
    if current.get("job_id") != token.get("job_id") or current.get("owner") != token.get("owner"): raise GitGuardError("GIT_LOCK_BUSY", {"reason": "LOCK_OWNERSHIP_MISMATCH", "current": current})
    (lock_dir / "owner.json").unlink()
    try:
        lock_dir.rmdir()
    except OSError as exc:
        raise GitGuardError("GIT_LOCK_BUSY", {"reason": "LOCK_DIRECTORY_NOT_EMPTY", "lock_dir": str(lock_dir)}) from exc


def compare_and_swap(repo: Path, remote_at_start: str) -> str:
    _run(repo, "fetch", REMOTE, DEV_BRANCH)
    remote_now = _run(repo, "rev-parse", f"{REMOTE}/{DEV_BRANCH}").stdout.strip()
    if remote_now != remote_at_start: raise GitGuardError("REMOTE_MOVED_RETRY_REQUIRED", {"remote_at_start": remote_at_start, "remote_now": remote_now})
    return remote_now


def validate_commit_scope(repo: Path, base_sha: str, candidate_sha: str, allowed_paths: set[str]) -> list[str]:
    dirty = _run(repo, "status", "--porcelain=v1", "--untracked-files=all").stdout.strip()
    if dirty: raise GitGuardError("GIT_SCOPE_VIOLATION", {"reason": "POST_COMMIT_WORKTREE_NOT_CLEAN", "status": dirty.splitlines()[:50]})
    actual = {line.strip() for line in _run(repo, "diff", "--name-only", base_sha, candidate_sha, "--").stdout.splitlines() if line.strip()}
    if actual != set(allowed_paths): raise GitGuardError("GIT_SCOPE_VIOLATION", {"allowed": sorted(allowed_paths), "actual": sorted(actual)})
    head = _run(repo, "rev-parse", "HEAD").stdout.strip()
    if head != candidate_sha: raise GitGuardError("GIT_SCOPE_VIOLATION", {"reason": "JOB_HEAD_MISMATCH", "head": head, "candidate": candidate_sha})
    return sorted(actual)


def scoped_push_env(job_id: str, owner: str, base: dict[str, str] | None = None) -> dict[str, str]:
    env = dict(base or os.environ)
    env["EDARSA_ALLOW_PUSH"] = "1"; env["EDARSA_PUSH_JOB_ID"] = job_id; env["EDARSA_PUSH_OWNER"] = owner
    return env


def authorized_push(repo: Path, *, args: list[str], job_id: str, owner: str, env_base: dict[str, str] | None = None):
    return _run(repo, *args, check=False, env=scoped_push_env(job_id, owner, env_base))


def post_push_verify(repo: Path, expected_sha: str) -> dict[str, Any]:
    _run(repo, "fetch", REMOTE, DEV_BRANCH)
    local = _run(repo, "rev-parse", "HEAD").stdout.strip(); remote = _run(repo, "rev-parse", f"{REMOTE}/{DEV_BRANCH}").stdout.strip()
    counts = _run(repo, "rev-list", "--left-right", "--count", f"{local}...{remote}").stdout.split()
    ahead, behind = (int(counts[0]), int(counts[1])) if len(counts) == 2 else (-1, -1)
    evidence = {"local_after": local, "remote_after_push": remote, "ahead_after": ahead, "behind_after": behind, "topology": f"{ahead}/{behind}"}
    if local != expected_sha or remote != expected_sha or ahead != 0 or behind != 0: raise GitGuardError("GIT_PUSH_FAILED", evidence)
    evidence["terminal_status"] = "CERTIFIED_GIT_SYNC"; return evidence


def fast_forward_refresh(repo: Path, *, expected_remote: str, job_id: str, owner: str, owner_pid: int | None = None) -> dict[str, Any]:
    token = acquire_writer_lock(repo, job_id=job_id, owner=owner, owner_pid=owner_pid)
    try:
        state = inspect_repository(repo, fetch=True)
        if state["remote_head"] != expected_remote: raise GitGuardError("REMOTE_MOVED_RETRY_REQUIRED", {"expected_remote": expected_remote, "actual_remote": state["remote_head"]})
        if state["worktree_dirty"]: raise GitGuardError("GIT_WORKTREE_NOT_CLEAN", state)
        if state["classification"] == "SYNC": return state
        if state["classification"] != "REMOTE_AHEAD_ONLY" or state["merge_base"] != state["local_head"]: raise GitGuardError("GIT_DIVERGENCE_BLOCKED", state)
        local = state["local_head"]; remote = state["remote_head"]
        update_tree = _run(repo, "read-tree", "-u", "-m", local, remote, check=False)
        if update_tree.returncode != 0: raise GitGuardError("GIT_DIVERGENCE_BLOCKED", {"reason": "FAST_FORWARD_WORKTREE_APPLY_FAILED", "output": (update_tree.stdout or "")[-2000:]})
        update_ref = _run(repo, "update-ref", f"refs/heads/{DEV_BRANCH}", remote, local, check=False)
        if update_ref.returncode != 0:
            _run(repo, "read-tree", "-u", "-m", remote, local, check=False)
            raise GitGuardError("GIT_DIVERGENCE_BLOCKED", {"reason": "FAST_FORWARD_REF_CAS_FAILED", "output": (update_ref.stdout or "")[-2000:]})
        final = inspect_repository(repo, fetch=False)
        if final["classification"] != "SYNC" or final["worktree_dirty"]: raise GitGuardError("GIT_DIVERGENCE_BLOCKED", {"reason": "FAST_FORWARD_POSTCHECK_FAILED", "state": final})
        return final
    finally:
        release_writer_lock(repo, token)


def main() -> int:
    parser = argparse.ArgumentParser(); sub = parser.add_subparsers(dest="command", required=True)
    p_inspect = sub.add_parser("inspect"); p_inspect.add_argument("--repo", default="/app"); p_inspect.add_argument("--no-fetch", action="store_true")
    p_acquire = sub.add_parser("acquire-lock"); p_acquire.add_argument("--repo", default="/app"); p_acquire.add_argument("--job-id", required=True); p_acquire.add_argument("--owner", required=True); p_acquire.add_argument("--owner-pid", type=int, default=0)
    p_release = sub.add_parser("release-lock"); p_release.add_argument("--repo", default="/app"); p_release.add_argument("--job-id", required=True); p_release.add_argument("--owner", required=True)
    p_refresh = sub.add_parser("refresh"); p_refresh.add_argument("--repo", default="/app"); p_refresh.add_argument("--expected-remote", required=True); p_refresh.add_argument("--job-id", required=True); p_refresh.add_argument("--owner", required=True); p_refresh.add_argument("--owner-pid", type=int, default=0)
    args = parser.parse_args(); repo = Path(args.repo).resolve()
    try:
        if args.command == "inspect": payload = inspect_repository(repo, fetch=not args.no_fetch)
        elif args.command == "acquire-lock": payload = acquire_writer_lock(repo, job_id=args.job_id, owner=args.owner, owner_pid=args.owner_pid or None)
        elif args.command == "release-lock":
            git_dir = _git_dir(repo); lock_dir = git_dir / "universal-worker-queue" / LOCK_NAME; current = _read_json(lock_dir / "owner.json"); token = {**current, "job_id": args.job_id, "owner": args.owner, "lock_dir": str(lock_dir)}; release_writer_lock(repo, token); payload = {"released": True, "job_id": args.job_id, "owner": args.owner}
        else: payload = fast_forward_refresh(repo, expected_remote=args.expected_remote, job_id=args.job_id, owner=args.owner, owner_pid=args.owner_pid or None)
    except GitGuardError as exc:
        print(json.dumps({"status": exc.code, "evidence": exc.evidence}, ensure_ascii=False)); return 1
    print(json.dumps(payload, ensure_ascii=False)); return 0


if __name__ == "__main__":
    raise SystemExit(main())

