import importlib.util
import os
import subprocess
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
GUARD = ROOT / 'tools' / 'mirror_sync' / 'git_divergence_guard.py'
DISPATCHER = ROOT / 'tools' / 'mirror_sync' / 'universal_job_dispatcher.py'
APPLY = ROOT / 'tools' / 'mirror_sync' / 'apply_remote_update.sh'
SUPERVISOR = ROOT / 'tools' / 'mirror_sync' / 'supervisor' / 'edarsahub-mirror-sync.conf'
BACKUP = ROOT / 'backup_a_github.sh'

def load_guard():
    spec = importlib.util.spec_from_file_location('git_divergence_guard_r1', GUARD)
    mod = importlib.util.module_from_spec(spec)
    assert spec and spec.loader
    spec.loader.exec_module(mod)
    return mod

def g(repo, *args, check=True, env=None):
    r = subprocess.run(['git', *args], cwd=repo, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env=env, check=False)
    if check and r.returncode != 0: raise AssertionError(r.stdout)
    return r

def setup_pair(tmp_path):
    remote = tmp_path / 'remote.git'; local = tmp_path / 'local'; peer = tmp_path / 'peer'
    g(tmp_path, 'init', '--bare', str(remote)); local.mkdir(); g(local, 'init'); g(local, 'config', 'user.email', 'test@example.com'); g(local, 'config', 'user.name', 'Test')
    (local / 'seed.txt').write_text('seed\n'); g(local, 'add', 'seed.txt'); g(local, 'commit', '-m', 'seed'); g(local, 'branch', '-M', 'Edarsahub_Desarrollo'); g(local, 'remote', 'add', 'origin', str(remote)); g(local, 'push', '-u', 'origin', 'Edarsahub_Desarrollo')
    g(tmp_path, 'clone', '-b', 'Edarsahub_Desarrollo', str(remote), str(peer)); g(peer, 'config', 'user.email', 'peer@example.com'); g(peer, 'config', 'user.name', 'Peer')
    return remote, local, peer

def commit(repo, name, content):
    (repo / name).write_text(content); g(repo, 'add', name); g(repo, 'commit', '-m', name)

def test_case_1_sync_pass(tmp_path):
    mod=load_guard(); _,local,_=setup_pair(tmp_path); s=mod.inspect_repository(local, fetch=True); assert s['classification']=='SYNC'; assert mod.mutation_policy(s)['allowed'] is True

def test_case_2_local_ahead_controlled_policy(tmp_path):
    mod=load_guard(); _,local,_=setup_pair(tmp_path); commit(local,'a.txt','a'); commit(local,'b.txt','b'); s=mod.inspect_repository(local, fetch=True); assert (s['ahead_count'],s['behind_count'])==(2,0); assert mod.mutation_policy(s)['allowed'] is False; assert mod.mutation_policy(s,allow_local_ahead=True)['allowed'] is True

def test_case_3_remote_ahead_blocks_write(tmp_path):
    mod=load_guard(); _,local,peer=setup_pair(tmp_path); commit(peer,'r1.txt','1'); commit(peer,'r2.txt','2'); g(peer,'push','origin','Edarsahub_Desarrollo'); s=mod.inspect_repository(local, fetch=True); p=mod.mutation_policy(s); assert (s['ahead_count'],s['behind_count'])==(0,2); assert p['allowed'] is False and p['reason']=='NEEDS_FAST_FORWARD_REFRESH'

def test_case_4_diverged_3_6_blocked(tmp_path):
    mod=load_guard(); _,local,peer=setup_pair(tmp_path)
    for i in range(3): commit(local,f'l{i}.txt',str(i))
    for i in range(6): commit(peer,f'r{i}.txt',str(i))
    g(peer,'push','origin','Edarsahub_Desarrollo'); s=mod.inspect_repository(local, fetch=True); p=mod.mutation_policy(s); assert (s['ahead_count'],s['behind_count'])==(3,6); assert s['classification']=='DIVERGED'; assert p['terminal_status']=='GIT_DIVERGENCE_BLOCKED'

def test_case_5_staged_blocks(tmp_path):
    mod=load_guard(); _,local,_=setup_pair(tmp_path); (local/'seed.txt').write_text('changed'); g(local,'add','seed.txt'); s=mod.inspect_repository(local, fetch=True); assert s['staged_count']==1; assert mod.mutation_policy(s)['terminal_status']=='GIT_WORKTREE_NOT_CLEAN'

def test_case_6_untracked_blocks(tmp_path):
    mod=load_guard(); _,local,_=setup_pair(tmp_path); (local/'new.txt').write_text('x'); s=mod.inspect_repository(local, fetch=True); assert s['untracked_count']==1; assert mod.mutation_policy(s)['terminal_status']=='GIT_WORKTREE_NOT_CLEAN'

def test_case_7_remote_moves_cancels_push(tmp_path):
    mod=load_guard(); _,local,peer=setup_pair(tmp_path); start=mod.inspect_repository(local,fetch=True)['remote_head']; commit(peer,'moved.txt','x'); g(peer,'push','origin','Edarsahub_Desarrollo')
    with pytest.raises(mod.GitGuardError,match='REMOTE_MOVED_RETRY_REQUIRED'): mod.compare_and_swap(local,start)

def install_push_guard(repo):
    hook=repo/'.git'/'hooks'/'pre-push'; hook.write_text('#!/bin/sh\n[ "${EDARSA_ALLOW_PUSH:-}" = 1 ] || { echo PUSH_DENIED; exit 9; }\n'); hook.chmod(0o755)

def test_case_8_push_without_guard_fails_no_pass(tmp_path):
    _,local,_=setup_pair(tmp_path); install_push_guard(local); commit(local,'guard.txt','x'); r=g(local,'push','origin','HEAD:Edarsahub_Desarrollo',check=False,env={k:v for k,v in os.environ.items() if k!='EDARSA_ALLOW_PUSH'}); assert r.returncode!=0; assert 'PASS' not in r.stdout

def test_case_9_authorized_fast_forward_topology_zero(tmp_path):
    mod=load_guard(); _,local,_=setup_pair(tmp_path); install_push_guard(local); commit(local,'ok.txt','x'); r=mod.authorized_push(local,args=['push','origin','HEAD:refs/heads/Edarsahub_Desarrollo'],job_id='case9',owner='test'); assert r.returncode==0; e=mod.post_push_verify(local,g(local,'rev-parse','HEAD').stdout.strip()); assert e['topology']=='0/0' and e['terminal_status']=='CERTIFIED_GIT_SYNC'

def test_case_10_two_writers_only_one_lock(tmp_path):
    mod=load_guard(); _,local,_=setup_pair(tmp_path); a=mod.acquire_writer_lock(local,job_id='a',owner='one',owner_pid=os.getpid())
    with pytest.raises(mod.GitGuardError,match='GIT_LOCK_BUSY'): mod.acquire_writer_lock(local,job_id='b',owner='two',owner_pid=os.getpid())
    mod.release_writer_lock(local,a)

def test_case_11_readonly_does_not_require_writer_lock(tmp_path):
    mod=load_guard(); _,local,_=setup_pair(tmp_path); a=mod.acquire_writer_lock(local,job_id='writer',owner='one',owner_pid=os.getpid()); assert mod.requires_writer_lock('READ_ONLY') is False; assert mod.requires_writer_lock('MUTATION') is True; mod.release_writer_lock(local,a)

def test_case_12_out_of_scope_file_fails(tmp_path):
    mod=load_guard(); _,local,_=setup_pair(tmp_path); base=g(local,'rev-parse','HEAD').stdout.strip(); commit(local,'allowed.txt','a'); commit(local,'extra.txt','b'); head=g(local,'rev-parse','HEAD').stdout.strip()
    with pytest.raises(mod.GitGuardError,match='GIT_SCOPE_VIOLATION'): mod.validate_commit_scope(local,base,head,{'allowed.txt'})

def executable_lines(path):
    return '\n'.join(line.strip() for line in path.read_text().splitlines() if line.strip() and not line.lstrip().startswith('#'))

def test_runtime_contract_has_no_automatic_merge_or_persistent_push_guard():
    commands = executable_lines(APPLY)
    assert 'git merge --ff-only' not in commands
    assert 'git pull' not in commands
    assert 'reset --hard' not in commands
    assert 'git clean' not in commands
    assert 'EDARSA_ALLOW_PUSH="1"' not in SUPERVISOR.read_text()
    assert 'export EDARSA_ALLOW_PUSH=1' not in BACKUP.read_text()

def test_dispatcher_uses_cas_and_no_replay_on_remote_move():
    text=DISPATCHER.read_text(); block=text.split('def integrate(',1)[1].split('def release_agent_guard_claim',1)[0]; assert 'compare_and_swap' in block; assert 'REMOTE_MOVED_RETRY_REQUIRED' not in block or 'exc.code' in block; assert 'CONCURRENT_REPLAY_REQUIRED' not in block; assert 'EDARSA_ALLOW_PUSH' in block; assert 'git push --force' not in text; assert 'force-with-lease' not in text
